(()=>{'use strict';const observed=new WeakSet();function sync(video){const item=video.closest('.pati-reel-item');if(!item)return;const paused=video.paused||video.ended;item.classList.toggle('buchee-reel-paused',paused);const play=item.querySelector('.buchee-pause-control');if(play){play.hidden=!paused;play.setAttribute('aria-label','Videoyu oynat')}const speed=item.querySelector('[data-action="reel-speed"]');if(speed)speed.remove();}
function scan(){document.querySelectorAll('#main-content .pati-reel-item video').forEach(video=>{const item=video.closest('.pati-reel-item');if(!item)return;let play=item.querySelector('.buchee-pause-control');if(!play){play=document.createElement('button');play.type='button';play.className='buchee-pause-control';play.textContent='▶';play.setAttribute('aria-label','Videoyu oynat');play.addEventListener('click',e=>{e.stopPropagation();e.preventDefault();if(video.paused){reelTogglePlay(play);sync(video)}});item.append(play)}if(!observed.has(video)){observed.add(video);['play','playing','pause','ended'].forEach(ev=>video.addEventListener(ev,()=>sync(video)))}sync(video)})}let pending=false;function queue(){if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;scan()})}new MutationObserver(queue).observe(document.getElementById('main-content')||document.body,{childList:true,subtree:true});document.addEventListener('DOMContentLoaded',queue);scan()})();